from taf.fdsw.rc.clients.http.http_client import RCHttpClient
from taf.fdsw.rc.interfaces.FDSW18A.autoconnection import AutoConfiguration18A
from taf.fdsw.rc.interfaces.FDSW18SP.fdsw import FDSW18SP


class FDSW18A(FDSW18SP):
    API_VERSION = "1.0"
    API_SCHEMA_VERSION = "2.0"
    VERSION_NAME = 'FDSW18A'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        super(FDSW18A, self).__init__(ip_address=ip_address, port=port, username=username, password=password,
                                      secure=secure)
        self._client = RCHttpClient(
            ip_address=ip_address,
            port=port,
            username=username,
            password=password,
            secure=secure,
            api_version=self.API_VERSION,
            api_schema_version=self.API_SCHEMA_VERSION
        )

        self._client.connect()
        self.autoconnection = AutoConfiguration18A(client=self._client)
